class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Try all possible subarrays [i, j]
        for i in range(n):
            for j in range(i, n):
                # Remove subarray from i to j
                # Remaining elements: nums[0:i] + nums[j+1:n]

                # Check if remaining array is strictly increasing
                is_strictly_increasing = True

                # First, check the prefix part (0 to i-1)
                if i > 0:
                    # Check if prefix is strictly increasing
                    for k in range(1, i):
                        if nums[k] <= nums[k-1]:
                            is_strictly_increasing = False
                            break
                    # If prefix is not strictly increasing, skip
                    if not is_strictly_increasing:
                        continue

                # Then, check the suffix part (j+1 to n-1)
                if j + 1 < n:
                    # Check if suffix is strictly increasing
                    for k in range(j + 2, n):
                        if nums[k] <= nums[k-1]:
                            is_strictly_increasing = False
                            break
                    # If suffix is not strictly increasing, skip
                    if not is_strictly_increasing:
                        continue

                # If both parts exist, check that last element of prefix < first element of suffix
                if i > 0 and j + 1 < n:
                    if nums[i-1] >= nums[j+1]:
                        is_strictly_increasing = False

                # If the remaining array is strictly increasing, count it
                if is_strictly_increasing:
                    count += 1

        return count

